/// <summary>
///     AVA <c>init</c> method.
/// </summary>
public void init()
{
    Args                        locArgs;

    frmKCS_KBVParameters    = KCS_KBVParameters::find();
    frmDataAreaId           = curExt();

    frmLogisticsPostalAddress.initValue();

    super();

    if(this.args())
    {
        locArgs = new Args();
        locArgs = this.args();

        if (locArgs.caller())
        {


            if(locArgs.caller().name() == formStr(AVAKBVBuildingProjectTable)
            || locArgs.caller().name() == formStr(AVAKBVBuildingProjectSearch) )
            {
                if(locArgs.record().TableId == TableNum(KCS_KBVBuildingProjectTable))
                {
                    frmKCS_KBVBuildingProjectTable  = locArgs.record();
                }
                KCS_KBVBuildingProjectTable.clear();
                KCS_KBVBuildingProjectTable.initValue();

                if (!frmKCS_KBVParameters)
                {
                    warning("@NDX:NXAConnotReadBPParameters");
                }
                else
                {
                    frmDataAreaIdNumberSeq = frmKCS_KBVParameters.KCS_DataAreaName; // company in which the NumSeq to use is

                    if (frmKCS_KBVParameters.KCS_KBVRelationID1)
                    {
                        KCS_KBVRelationID1.text(frmKCS_KBVParameters.KCS_KBVRelationID1);
                        DirPartyId1.allowEdit(true);
                        editContactPersonName1.allowEdit(true);
                    }
                    if (frmKCS_KBVParameters.KCS_KBVRelationID2)
                    {
                        KCS_KBVRelationID2.text(frmKCS_KBVParameters.KCS_KBVRelationID2);
                        DirPartyId2.allowEdit(true);
                        editContactPersonName2.allowEdit(true);
                    }
                }
            }
        }

    }
}

