/// <summary>
///     AVA <c>createRelations</c> method.
///     last modified: PaffH 12.09.25
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///     <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
void createRelations(KCS_KBVBuildingProjectID _kcs_KBVBuildingProjectID)
{
    KCS_KBVRelationsToBV    locKCS_KBVRelationsToBV;

    KCS_KBVRelationID       locKCS_KBVRelationID;
    DirPartyRecId           locDirPartyRecId;
    ContactPersonId         locContactPersonId;

    //todo
    changecompany(frmDataAreaId)
    {
        locKCS_KBVRelationID    = KCS_KBVRelationID1.valueStr();
        locDirPartyRecId        = DirPartyId1.value();
        locContactPersonId      = ContactPersonId1.valueStr();

        if (locKCS_KBVRelationID && (locDirPartyRecId || locContactPersonId))
        {
            locKCS_KBVRelationsToBV.clear();
            locKCS_KBVRelationsToBV.KCS_KBVBuildingProjectID    = _kcs_KBVBuildingProjectID;
            locKCS_KBVRelationsToBV.KCS_KBVRelationID           = locKCS_KBVRelationID;
            locKCS_KBVRelationsToBV.DirPartyId                  = locDirPartyRecId;
            locKCS_KBVRelationsToBV.ContactPersonId             = locContactPersonId;
            locKCS_KBVRelationsToBV.ContactPersonParty          = ContactPerson::find(locContactPersonId).Party;
            locKCS_KBVRelationsToBV.insert();

            smmBusRelTable      checkSmmBusRelTable;
            checkSmmBusRelTable = smmBusRelTable::findByParty(locDirPartyRecId);
            if (!checkSmmBusRelTable.RecId)
            {
                KCS_KBVBuildingProjectTable::find(_kcs_KBVBuildingProjectID).createSmmBusRelTableForCompany(locDirPartyRecId);
            }
        }

        locKCS_KBVRelationID    = KCS_KBVRelationID2.valueStr();
        locDirPartyRecId        = DirPartyId2.value();
        locContactPersonId      = ContactPersonId2.valueStr();

        if (locKCS_KBVRelationID && (locDirPartyRecId || locContactPersonId))
        {
            locKCS_KBVRelationsToBV.clear();
            locKCS_KBVRelationsToBV.KCS_KBVBuildingProjectID    = _kcs_KBVBuildingProjectID;
            locKCS_KBVRelationsToBV.KCS_KBVRelationID           = locKCS_KBVRelationID;
            locKCS_KBVRelationsToBV.DirPartyId                  = locDirPartyRecId;
            locKCS_KBVRelationsToBV.ContactPersonId             = locContactPersonId;
            locKCS_KBVRelationsToBV.ContactPersonParty          = ContactPerson::find(locContactPersonId).Party;
            locKCS_KBVRelationsToBV.insert();

            smmBusRelTable      checkSmmBusRelTable;
            checkSmmBusRelTable = smmBusRelTable::findByParty(locDirPartyRecId);
            if (!checkSmmBusRelTable.RecId)
            {
                KCS_KBVBuildingProjectTable::find(_kcs_KBVBuildingProjectID).createSmmBusRelTableForCompany(locDirPartyRecId);
            }
        }
    }
}

/// <summary>
///     AVA <c>closeOk</c> method.
/// </summary>
public void closeOk()
{
    Args            locArgs;
    MenuFunction    menuFunctionCreateRequest;
    Args            argsCreateRequest;
    FormRun         FormRunCaller;


    locArgs = element.args();

    FormRunCaller   = locArgs.caller();

    frmCreateBPOK   = true;

    super();

    if (locArgs.caller())
    {
        if(locArgs.caller().name() == formStr(AVAKBVBuildingProjectTable)
        || locArgs.caller().name() == formStr(AVAKBVBuildingProjectSearch))
        {
            changecompany(frmDataAreaId)
            {
                /* record allready inserted
                newRecord.clear();

                Buf2Buf(KCS_KBVBuildingProjectTable, newRecord);
                newRecord.KCS_KBVBuildingProjectID        = '';
                newRecord.insert();

                if(newRecord.RecId)
                {
                    element.createRelations(newRecord.KCS_KBVBuildingProjectID);
                }
                */

                if (KCS_KBVBuildingProjectTable.RecId)
                {
                    element.createRelations(KCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);

                    locArgs.caller().parmCreateBPOK(frmCreateBPOK);
                    locArgs.caller().parmCreateBPOKAndNewRequest(frmCreateBPOKAndNewRequest);
                    locArgs.caller().parmKCS_KBVBuildingProjectTableCreated(KCS_KBVBuildingProjectTable);

                    if(     frmCreateBPOK 
                        &&  frmCreateBPOKAndNewRequest
                        &&  KCS_KBVBuildingProjectTable.RecId   )
                    {
                        // Create request
                        argsCreateRequest           = new Args();
                        argsCreateRequest.record(KCS_KBVBuildingProjectTable);
                        //argsCreateRequest.caller(this);

                        argsCreateRequest.caller(locArgs.caller());

                        menuFunctionCreateRequest   = new MenuFunction(menuItemDisplayStr(AVAKBVCreateRequestTable), MenuItemType::Display);
                        menuFunctionCreateRequest.run(argsCreateRequest);
                    }
                }

                FormDataSource  refreshDS = FormDataUtil::getFormDataSource(frmKCS_KBVBuildingProjectTable);
                if(refreshDS)
                {
                    refreshDS.research(true);
                }
                if (formHasMethod(FormRunCaller, literalStr(afterKCS_KBVBuildingProjectCreation)))
                {
                    FormRunCaller.afterKCS_KBVBuildingProjectCreation();
                }

                if (locArgs.caller().name() == formStr(AVAKBVBuildingProjectSearch) && !frmCreateBPOKAndNewRequest)
                {
                    Args newargs = new Args();
                    newargs.caller(this);
                    newArgs.record(KCS_KBVBuildingProjectTable);
                    newargs.parm('CreateFromSearch');
                    new MenuFunction(menuItemDisplayStr(AVAKBVBuildingProjectTable), MenuItemType::Display).run(newArgs);
                }
            }
        }
    }
}

/// <summary>
///     AVA <c>run</c> method.
/// </summary>
public void run()
{
    KCS_KBVBuildingProjectTable_ds.create();

    Args        locArgs = element.args();
    FormRun     callerFormRun = locArgs.caller();
    if (locArgs && locArgs.caller() is FormRun &&  callerFormRun.name() == formStr(AVAKBVBuildingProjectSearch))
    {
        if (formHasMethod(locArgs.caller(),identifierStr('getFilterParameters')))
        {
            container  searchFilter = callerFormRun.getFilterParameters();
            LogisticsAddressCity            logisticsAddressCity = LogisticsAddressCity::findCity(conPeek(searchFilter,5));
            LogisticsAddressCountryRegion   logisticsAddressCountryRegion;

            if (conpeek(searchFilter,4) != '')
            {
                logisticsAddressCountryRegion= LogisticsAddressCountryRegion::find(conPeek(searchFilter,4));
            }
            else
            {
                logisticsAddressCountryRegion = LogisticsAddressCountryRegion::find(SysUserInfo::find(curUserId()).DefaultCountryRegion);
            }

            KCS_KBVBuildingProjectTable.KCS_KBVSubject                 = conPeek(searchFilter,3) + ' ' + conPeek(searchFilter,2);
            KCS_KBVBuildingProjectTable.AddressCity                    = logisticsAddressCity.Name;
            KCS_KBVBuildingProjectTable.AddressCountryRegionId         = logisticsAddressCountryRegion.CountryRegionId;
            if (!KCS_KBVBuildingProjectTable.AddressCountryRegionId)
            {
                KCS_KBVBuildingProjectTable.AddressCountryRegionId = LogisticsAddressCity::findCity(KCS_KBVBuildingProjectTable.AddressCity).CountryRegionId;
            }

            KCS_KBVBuildingProjectTable.KCS_KBVTenderFirstPositionQty  = conPeek(searchFilter,6);
            KCS_KBVBuildingProjectTable.KCS_KBVTenderFirstPosition     = conPeek(searchFilter,7);
            KCS_KBVBuildingProjectTable.KCS_KBVTenderID                = conPeek(searchFilter,11);
            KCS_KBVBuildingProjectTable.KCS_KBVPlacingNumber           = conPeek(searchFilter,10);

            LogisticsPostalAddressView                  logisticsPostalAddressView;

            if (KCS_KBVBuildingProjectTable.AddressCity)
            {
                select firstonly ZipCode from logisticsPostalAddressView
                where  logisticsPostalAddressView.City == KCS_KBVBuildingProjectTable.AddressCity;

                KCS_KBVBuildingProjectTable.AddressZipCodeId               = logisticsPostalAddressView.ZipCode;
            }

            DirPartyTable        dirPartyTable;
            ContactPerson        contactPerson;
            DirPartyTable        contactPersonPartyTable;

            select firstonly dirPartyTable
                where dirPartyTable.Name like  conPeek(searchFilter,8);

            select firstonly contactPerson
                join contactPersonPartyTable
                    where contactPersonPartyTable.RecId == contactPerson.Party
                       && contactPersonPartyTable.Name like conPeek(searchFilter,9);

          /*  KCS_KBVRelationID       relationId1 = KCS_KBVParameters::find().KCS_KBVRelationID1;

            if (relationId1)
            {
                KCS_KBVRelationID1.text(relationId1);
            }      */
            relationDirPartyId1    =  dirPartyTable.RecId;
            DirPartyId1.value(dirPartyTable.RecId);
            ContactPersonId1.text(contactPerson.ContactPersonId);

        }
    }

    super();
}

/// <summary>
///     AVA <c>createSmmBusRelTableForCompany</c> method.
/// </summary>
/// <param name="_dirPartyRecId">
///     <c>DirPartyRecId</c> as type
/// </param>
public void createSmmBusRelTableForCompany(DirPartyRecId _dirPartyRecId)
{
    smmBusRelTable           locsmmBusRelTable;
    LogisticsPostalAddress   address = DirParty::primaryPostalAddress(_dirPartyRecId);
    CompanyInfo              companyInfo;
    smmBusRelTable           companyBusRelTable;
    ContactPerson            contactPerson;
    List                     companyContactList = new List(Types::Record);
    ListIterator             companyContactListIterator;

    while select companyInfo
        where companyInfo.DataArea != 'DAT'
    {
        changecompany(companyInfo.DataArea)
        {
            ContactPerson       companyContactPerson;
            companyBusRelTable = smmBusRelTable::findByParty(_dirPartyRecId);
            if (companyBusRelTable.RecId)
            {
                while select companyContactPerson
                    where companyContactPerson.ContactForParty == _dirPartyRecId
                {
                    companyContactList.addEnd(companyContactPerson);
                }
                break;
            }
        }
    }

    locsmmBusRelTable.initValue();
    locsmmBusRelTable.initFromDirParty(DirParty::constructFromPartyRecId(_dirPartyRecId));
    locsmmBusRelTable.BusRelAccount = smmParameters::getNumber(smmNumbSeqUsed::BusRel);
    locsmmBusRelTable.Party         = _dirPartyRecId;
    locsmmBusRelTable.NDX_initSalesGroupAndDistrictFromAddr(address.ZipCode, address.CountryRegionId, locsmmBusRelTable.dataAreaId);
    if (companyBusRelTable)
    {
        locsmmBusRelTable.copyFromSmmBusRelTable(companyBusRelTable);
    }
    locsmmBusRelTable.insert();

    ContactPerson            companyContactPerson;
    companyContactListIterator = new ListIterator(companyContactList);
    while (companyContactListIterator.more())
    {
        companyContactPerson = companyContactListIterator.value();
        contactPerson.clear();
        contactPerson.initValue();
        contactPerson.copyFromCompanyContactPerson(companyContactPerson);
        contactPerson.initFromBusRel(companyBusRelTable);
        contactPerson.initFromParty(DirPartyTable::findRec(contactPerson.Party));
        contactPerson.ContactPersonId  = NumberSeq::newGetNum(ContactPerson::numRefContactPersonId()).num();
        contactPerson.insert();
        companyContactListIterator.next();
    }
}

/// <summary>
///     AVA <c>validateWrite</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean validateWrite()
{
    boolean ret;

    KCS_KBVSubject locKCS_KBVSubject;

    ret = super();

    locKCS_KBVSubject = KCS_KBVBuildingProjectTable::findByName(KCS_KBVBuildingProjectTable_KCS_KBVSubject.valueStr()).KCS_KBVSubject;

    if(ret && locKCS_KBVSubject)
    {
        ret = checkFailed(strFmt("@NDX:NXABPWithNameP1AlreadyExist", locKCS_KBVSubject));
    }

    if(ret)
    {
        KCS_KBVBuildingProjectTable.setKCS_KBVBuildingProjectIDNumberSeq();
    }

    return ret;
}

