/// <summary>
///     AVA <c>modified</c> method.
/// </summary>
public void modified()
{
    LogisticsAddressParameters  locLogisticsAddressParameters;
    FormStringControl control;

    locLogisticsAddressParameters = LogisticsAddressParameters::find();

    super();

    if (frmLogisticsPostalAddress.City)
    {
        if (locLogisticsAddressParameters.ValidateCity)
        {
            control = element.selectedControl();

            if (!control)
            {
                element.selectControl(KCS_KBVBuildingProjectTable_AddressCity);
                control = element.selectedControl();
            }
            if (!frmLogisticsPostalAddress.CityRecId && LogisticsAddressCity::cityCount(frmLogisticsPostalAddress.City, frmLogisticsPostalAddress.CountryRegionId, frmLogisticsPostalAddress.State) > 1)
            {
                KCS_KBVBuildingProjectTable_ds.object(fieldNum(KCS_KBVBuildingProjectTable, AddressCity)).lookup(control, frmLogisticsPostalAddress.City);
            }
        }
        //element.updateControlBasedOnCountry();
        KCS_KBVBuildingProjectTable.AddressZipCodeId    = frmLogisticsPostalAddress.ZipCode;
        KCS_KBVBuildingProjectTable.AddressCity         = frmLogisticsPostalAddress.City;
    }
}

