/// <summary>
///     AVA <c>resolveAmbiguousReference</c> method.
/// </summary>
/// <param name="_formControl">
///     <c>FormControl</c> as type
/// </param>
/// <returns>
///     <c>str</c> as return value
/// </returns>
public str resolveAmbiguousReference(FormControl _formControl)
{
    str ret;

    // Don't call the built-in ambiguous reference resolver. Use the user-provided value all the time.
    // ret = super(_formControl);

    FormStringControl formStringControl = _formControl as FormStringControl;

    if (formStringControl != null)
    {
        ret = formStringControl.text();
    }

    return ret;
}

