/// <summary>
///     AVA <c>modified</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean modified()
{
    boolean ret;

    ret = super();

    smmBusRelTable      checkSmmBusRelTable;
    checkSmmBusRelTable = smmBusRelTable::findByParty(DirPartyId1.value());
    if (DirPartyId1.value() != 0)
    {
        if (!checkSmmBusRelTable.RecId )
        {
            element.createSmmBusRelTableForCompany(DirPartyId1.value());
        }

        if(!AVAKBVDirPartyContactPersonHelper::checkContactPersonOnDirPartyId(DirPartyId1.value(), ContactPersonId1.valueStr()))
        {
            ContactPersonId1.text('');
            editContactPersonName1.text('');
            relationContactPersonId1 = '';
        }
    }
    relationDirPartyId1 = DirPartyId1.value();

    return ret;
}

