///     <c>boolean</c> as return value
/// </returns>
public boolean modified()
{
    boolean ret;

    ret = super();

    smmBusRelTable      checkSmmBusRelTable;
    if(DirPartyId2.value() != 0)
    {
        checkSmmBusRelTable = smmBusRelTable::findByParty(DirPartyId2.value());
        if (!checkSmmBusRelTable.RecId)
        {
            element.createSmmBusRelTableForCompany(DirPartyId2.value());
        }

        if(!AVAKBVDirPartyContactPersonHelper::checkContactPersonOnDirPartyId(DirPartyId2.value(), ContactPersonId2.valueStr()))
        {
            ContactPersonId2.text('');
            editContactPersonName2.text('');
            relationContactPersonId2 = '';
        }
    }
    relationDirPartyId2 = DirPartyId2.value();

    return ret;
}

